import{_ as s,o as n,c as e,am as p}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"Seata","description":"","frontmatter":{"title":"Seata","excerpt":"SpringCloud_组件基本使用_Seata","date":"2023-12-04 17:12:55","updated":"2023-12-04 17:12:55"},"headers":[],"relativePath":"框架/微服务分布式/框架 SpringCloud/Seata.md","filePath":"框架/微服务分布式/框架 SpringCloud/Seata.md","lastUpdated":null}'),t={name:"框架/微服务分布式/框架 SpringCloud/Seata.md"};function l(i,a,o,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h3 id="_1、什么是分布式事务" tabindex="-1">1、什么是分布式事务 <a class="header-anchor" href="#_1、什么是分布式事务" aria-label="Permalink to &quot;1、什么是分布式事务&quot;">​</a></h3><p>首先理解一下，为什么会用到分布式事务。</p><p>在分布式服务中，服务A中通过feign来调用服务B的方法，但是服务B的方法并不归属于服务A的事务体系中，因此如果此时服务B报错，并不会导致已经执行了的服务A的操作回退。</p><p>想要让服务A回退，那么就要让服务B纳入到服务A的事务体系中，也就是两者是同一个事务ID。这就是我们的分布式事务，它<strong>可以跨越服务来实现事务</strong>。</p><p>想要实现分布式事务，我们有多种方式，可以通过像redis这样的中间件来实现。</p><p>但也可以用到我们今天介绍的seata组件来实现。甚至发展至今，一般我们谈到分布式事务，基本上seata已经成了我们的不二选择。</p><h3 id="_2、seata-是什么" tabindex="-1">2、Seata 是什么 <a class="header-anchor" href="#_2、seata-是什么" aria-label="Permalink to &quot;2、Seata 是什么&quot;">​</a></h3><p>Seata 是一款分布式事务解决方案，为微服务架构提供了强一致性的分布式事务支持。提供了全局事务管理和本地事务协调的功能，可以用于确保多个微服务之间的事务操作的一致性；提供了 AT、TCC、SAGA和XA等几种事务模式。</p><p>常见的两种分布式事务模型：AT 模型（基于 TCC，Try-Confirm-Cancel）和 TCC 模型（基于两阶段提交）。</p><blockquote><p>AT模型</p></blockquote><p>默认使用的是 AT模式</p><ol><li>在业务表所在的数据库中创建一个名为undo_log的表，用于记录回滚SQL，即与执行SQL相反的SQL（例如，执行insert则对应delete）。</li><li>当业务表执行操作时，Seata会解析执行的SQL，生成回滚SQL并存储到undo_log表中。</li><li>在本地事务提交前，向Seata服务端注册分支，申请业务表中对应数据行的全局锁，阻止其他事务对该数据进行更新操作。</li><li>本地事务提交时，业务数据的更新和生成的undo log一起提交。</li><li>将本地事务执行结果报告给Seata服务端，多个服务的本地事务使用相同的事务ID和分支ID记录在Seata服务端。</li><li>如果某个本地事务发生错误，Seata服务端发起对应分支的回滚请求。</li><li>同时开启本地事务，通过事务ID和分支ID查询undo_log表，执行回滚SQL，并将执行结果报告给Seata服务端。</li><li>如果没有错误发生，Seata服务端会在对应分支上发起请求，异步批量删除undo_log表中的记录。</li></ol><p>总体来说，Seata服务端记录了所有本地事务，同时在每个库中记录了 undo log。</p><p>当发生错误时，通过事务ID和分支ID找到同一组的所有本地事务，利用记录的undo log统一回退数据。</p><h3 id="_3、使用-seata-的基本步骤" tabindex="-1">3、使用 Seata 的基本步骤 <a class="header-anchor" href="#_3、使用-seata-的基本步骤" aria-label="Permalink to &quot;3、使用 Seata 的基本步骤&quot;">​</a></h3><p>seata分为服务端（TC）和客户端（TM,RM）,</p><p>客户端通过引入jar包来使用。服务端需要我们单独安装。</p><ul><li>TC(Transaction Coordinator)：事务协调器，维护全局事务的运行状态，协调和落实全局事务的回滚提交</li><li>TM(Transaction Manager)：控制全局事务的边界，负责开启一个全局事务，并最终发起全局事务提交或回滚的决议</li><li>RM(Resource Manager)：控制分支（本地）事务，负责分支注册、状态汇报，并接受TC的指令，驱动本地事务的提交和回滚</li></ul><h4 id="_1-部署-seata-服务器" tabindex="-1">1. 部署 Seata 服务器 <a class="header-anchor" href="#_1-部署-seata-服务器" aria-label="Permalink to &quot;1. 部署 Seata 服务器&quot;">​</a></h4><p>服务端下载地址： <a href="https://github.com/seata/seata/releases" target="_blank" rel="noreferrer">https://github.com/seata/seata/releases</a></p><p>部署过程：略</p><h4 id="_2-seata客户端配置" tabindex="-1">2. seata客户端配置 <a class="header-anchor" href="#_2-seata客户端配置" aria-label="Permalink to &quot;2. seata客户端配置&quot;">​</a></h4><p>在微服务的项目中，添加 Seata 的依赖。如果使用 Maven，可以在项目的 <code>pom.xml</code> 文件中添加以下依赖：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>    &lt;groupId&gt;io.seata&lt;/groupId&gt;</span></span>
<span class="line"><span>	    &lt;artifactId&gt;·-all&lt;/artifactId&gt;</span></span>
<span class="line"><span>    &lt;version&gt;1.5.2&lt;/version&gt; &lt;!-- 请根据实际情况选择版本 --&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><p>配置文件</p><p>在微服务的配置文件中，配置 Seata 客户端。通常需要指定 Seata 服务器的地址等信息。以下是一个示例配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seata:</span></span>
<span class="line"><span>  application-id: my-app</span></span>
<span class="line"><span>  tx-service-group: my-tx-group</span></span>
<span class="line"><span>  enabled: true</span></span>
<span class="line"><span>  config:</span></span>
<span class="line"><span>    type: nacos</span></span>
<span class="line"><span>    nacos:</span></span>
<span class="line"><span>      serverAddr: nacos-server:8848</span></span>
<span class="line"><span>      groupId: SEATA_GROUP</span></span>
<span class="line"><span>      namespace: &quot;&quot;</span></span>
<span class="line"><span>  registry:</span></span>
<span class="line"><span>    type: nacos</span></span>
<span class="line"><span>    nacos:</span></span>
<span class="line"><span>      serverAddr: nacos-server:8848</span></span>
<span class="line"><span>      groupId: SEATA_GROUP</span></span>
<span class="line"><span>      namespace: &quot;&quot;</span></span>
<span class="line"><span>  service:</span></span>
<span class="line"><span>    vgroup: &quot;my-tx-group&quot;</span></span>
<span class="line"><span>    group: &quot;my-tx-group&quot;</span></span></code></pre></div><h4 id="添加事务注解" tabindex="-1">添加事务注解 <a class="header-anchor" href="#添加事务注解" aria-label="Permalink to &quot;添加事务注解&quot;">​</a></h4><p>使用 @GlobalTransactional 注解</p><p>在需要分布式事务的方法上，使用 <code>@GlobalTransactional</code> 注解标记。这个注解表示这个方法需要参与全局事务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import io.seata.spring.annotation.GlobalTransactional;</span></span>
<span class="line"><span>import org.springframework.stereotype.Service;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@Service</span></span>
<span class="line"><span>public class MyService {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @GlobalTransactional(rollbackFor = Exception.class)</span></span>
<span class="line"><span>    public void businessMethod() {</span></span>
<span class="line"><span>        // 业务逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><hr><p>参考</p><ul><li><a href="https://blog.csdn.net/github_38592071/article/details/131136986" target="_blank" rel="noreferrer">https://blog.csdn.net/github_38592071/article/details/131136986</a></li><li><a href="https://juejin.cn/post/7087551217781620749" target="_blank" rel="noreferrer">https://juejin.cn/post/7087551217781620749</a></li><li><a href="https://seata.io/zh-cn/docs/overview/what-is-seata.html" target="_blank" rel="noreferrer">https://seata.io/zh-cn/docs/overview/what-is-seata.html</a></li></ul>`,34)])])}const g=s(t,[["render",l]]);export{h as __pageData,g as default};
